(function(){
  function C(n){ try { return Java.loadClass(n); } catch (e) { return null; } }
  if (typeof AutoJS === 'undefined') { throw new Error('端点: server 侧 AutoJS 全局缺失（通道未注入）'); }
  var ps = AutoJS.players();
  if (ps === null || ps.length < 1) { throw new Error('端点: 世界内没有玩家，无法开店'); }
  var p = ps[0];
  var Op = C('com.merlinkitsune.astral_dice.shop.ChipShopOpener');
  if (Op === null) { throw new Error('端点: ChipShopOpener 不可解析（类路径变更？）'); }
  Op.open(p);
  return { opened: true, player: String(p.getName().getString()) };
})()

(function(){
  function C(n){ try { return Java.loadClass(n); } catch (e) { return null; } }
  var mc = C('net.minecraft.client.Minecraft').getInstance();
  var s = mc.screen;
  if (s === null) { return false; }
  return String(s).indexOf('Shop') >= 0;
})()
